<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Capacitor } from '@capacitor/core'
import { Keyboard } from '@capacitor/keyboard'
import { ArrowLeft, ChevronDown, Save, Trash2 } from '@lucide/vue'
import { useRoute, useRouter } from 'vue-router'
import type { Category, LedgerType } from '@/domain/models/category'
import { formatCents, parseAmountToCents } from '@/domain/services/money'
import { useAppStore } from '@/stores/app-store'
import AppDialog from '@/components/AppDialog.vue'
import CategoryIcon from '@/components/CategoryIcon.vue'
import CategoryPicker from '@/features/categories/CategoryPicker.vue'
import DateTimePickerSheet from '@/features/transactions/DateTimePickerSheet.vue'
import { formatRecordDateTime } from '@/features/transactions/date-time'

const route = useRoute()
const router = useRouter()
const store = useAppStore()
const editingId = computed(() => typeof route.params.id === 'string' ? route.params.id : undefined)
const type = ref<LedgerType>('expense')
const amountText = ref('')
const categoryId = ref('')
const bookedAt = ref(new Date())
const dateCustomized = ref(false)
const note = ref('')
const pickerOpen = ref(false)
const datePickerOpen = ref(false)
const activationOpen = ref(false)
const deleteOpen = ref(false)
const saving = ref(false)
const deleting = ref(false)
const recentIds = ref<string[]>([])
const amountInput = ref<HTMLInputElement>()
let focusTimer: number | undefined

const activeCategories = computed(() => {
  const rows = store.categories.filter((category) => category.type === type.value && !category.disabled)
  const activeParents = new Set(rows.filter((category) => category.parentId === null).map((category) => category.id))
  return rows.filter((category) => category.parentId === null || activeParents.has(category.parentId))
})
const selectedCategory = computed(() => store.categories.find((category) => category.id === categoryId.value))
const dateLabel = computed(() => formatRecordDateTime(bookedAt.value, dateCustomized.value))

async function loadRecent(): Promise<void> {
  recentIds.value = (await store.repository.recentCategories(type.value)).map((category) => category.id)
}

function isAvailableCategory(category: Category | undefined, targetType: LedgerType): category is Category {
  if (!category || category.type !== targetType || category.parentId === null || category.disabled) return false
  const parent = store.categories.find((item) => item.id === category.parentId)
  return Boolean(parent && parent.parentId === null && !parent.disabled)
}

async function chooseDefault(): Promise<void> {
  const targetType = type.value
  const settings = await store.repository.getSettings()
  if (type.value !== targetType) return
  const remembered = store.categories.find((category) => category.id === settings.lastSelectedCategoryIds?.[targetType])
  const current = selectedCategory.value
  if (isAvailableCategory(current, targetType)) return
  categoryId.value = isAvailableCategory(remembered, targetType)
    ? remembered.id
    : activeCategories.value.find((category) => category.parentId !== null)?.id ?? ''
}

function openCategoryPicker(): void {
  const focused = document.activeElement
  if (focused instanceof HTMLElement) focused.blur()
  pickerOpen.value = true
  if (Capacitor.getPlatform() === 'android') void Keyboard.hide().catch(() => undefined)
}

function closeCategoryPicker(): void {
  pickerOpen.value = false
}

function returnAfterRecordChange(): void {
  const back = window.history.state?.back
  if (typeof back === 'string' && back.startsWith('/')) router.back()
  else void router.replace('/')
}

onMounted(async () => {
  await store.initialize()
  if (!store.canWrite) activationOpen.value = true
  if (editingId.value) {
    const existing = await store.repository.getTransaction(editingId.value)
    if (!existing) { store.notify('没有找到这条流水', 'error'); await router.replace('/transactions'); return }
    type.value = existing.type
    amountText.value = formatCents(existing.amountCents, false)
    categoryId.value = existing.categoryId
    bookedAt.value = new Date(existing.bookedAt)
    dateCustomized.value = true
    note.value = existing.note
  } else await chooseDefault()
  await loadRecent()
  await nextTick()
  if (!store.canWrite) return
  focusTimer = window.setTimeout(async () => {
    amountInput.value?.focus({ preventScroll: true })
    amountInput.value?.select()
    if (Capacitor.getPlatform() === 'android') await Keyboard.show().catch(() => undefined)
  }, 180)
})
onBeforeUnmount(() => { if (focusTimer) window.clearTimeout(focusTimer) })

watch(type, async () => { await chooseDefault(); await loadRecent() })

async function selectCategory(category: Category): Promise<void> {
  categoryId.value = category.id
  closeCategoryPicker()
  const settings = await store.repository.getSettings()
  await store.repository.putSettings({
    ...settings,
    lastSelectedCategoryIds: { ...settings.lastSelectedCategoryIds, [category.type]: category.id },
  })
}

function confirmDate(value: Date): void {
  bookedAt.value = value
  dateCustomized.value = true
  datePickerOpen.value = false
}

async function save(): Promise<void> {
  if (!store.canWrite) { activationOpen.value = true; return }
  let amountCents: number
  try { amountCents = parseAmountToCents(amountText.value) }
  catch (cause) { store.notify(cause instanceof Error ? cause.message : '请输入有效金额', 'error'); return }
  const category = selectedCategory.value
  if (!category || category.parentId === null) { store.notify('请选择分类', 'error'); return }
  if (Number.isNaN(bookedAt.value.getTime())) { store.notify('请选择有效日期', 'error'); return }
  saving.value = true
  try {
    const now = new Date().toISOString()
    const previous = editingId.value ? await store.repository.getTransaction(editingId.value) : undefined
    await store.repository.putTransaction({
      id: editingId.value ?? crypto.randomUUID(),
      type: type.value,
      amountCents,
      categoryId: category.id,
      bookedAt: bookedAt.value.toISOString(),
      note: note.value.trim(),
      createdAt: previous?.createdAt ?? now,
      updatedAt: now,
    })
    await store.refresh()
    store.notify(editingId.value ? '流水已更新' : '记账成功', 'success')
    returnAfterRecordChange()
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '保存失败，请重试', 'error')
  } finally { saving.value = false }
}

async function remove(): Promise<void> {
  if (!editingId.value || !store.canWrite) return
  deleting.value = true
  try {
    await store.repository.deleteTransaction(editingId.value)
    await store.refresh()
    store.notify('流水已删除', 'success')
    returnAfterRecordChange()
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '删除失败，请重试', 'error')
  } finally {
    deleting.value = false
    deleteOpen.value = false
  }
}
</script>

<template>
  <main class="record-page">
    <header class="record-header">
      <button type="button" class="header-button" aria-label="返回" @click="router.back()"><ArrowLeft :size="22" /></button>
      <h1>{{ editingId ? '编辑流水' : '新增流水' }}</h1>
      <button type="button" class="save-button" :disabled="saving" @click="save"><Save :size="18" aria-hidden="true" />{{ saving ? '保存中' : '保存' }}</button>
    </header>

    <section class="type-wrap">
      <div class="segmented" aria-label="收支类型">
        <button type="button" :class="{ active: type === 'expense' }" :aria-pressed="type === 'expense'" @click="type = 'expense'">支出</button>
        <button type="button" :class="{ active: type === 'income' }" :aria-pressed="type === 'income'" @click="type = 'income'">收入</button>
      </div>
    </section>

    <form class="record-form card" @submit.prevent="save">
      <label class="form-row">
        <span>金额</span>
        <input ref="amountInput" v-model="amountText" inputmode="decimal" autocomplete="off" placeholder="0.00" :class="type" autofocus />
      </label>
      <button class="form-row select-row" type="button" @click="openCategoryPicker">
        <span>分类</span>
        <span class="row-value">
          <CategoryIcon v-if="selectedCategory" :name="selectedCategory.icon" :size="20" />
          {{ selectedCategory?.name ?? '请选择' }}<ChevronDown :size="19" aria-hidden="true" />
        </span>
      </button>
      <button class="form-row select-row" type="button" :aria-label="`日期 ${dateLabel}`" @click="datePickerOpen = true">
        <span>日期</span>
        <span class="row-value">{{ dateLabel }}<ChevronDown :size="19" aria-hidden="true" /></span>
      </button>
      <label class="form-row">
        <span>备注</span>
        <input v-model="note" maxlength="100" placeholder="选填" />
      </label>
    </form>
    <button v-if="editingId" class="delete-record button danger" type="button" @click="deleteOpen = true"><Trash2 :size="19" />删除这条流水</button>
  </main>

  <CategoryPicker :open="pickerOpen" :type="type" :categories="store.categories" :selected-id="categoryId" :recent-ids="recentIds" @close="closeCategoryPicker" @select="selectCategory" @add="router.push({ name: 'category-new', query: { type } })" />
  <DateTimePickerSheet :open="datePickerOpen" :initial="bookedAt" @close="datePickerOpen = false" @confirm="confirmDate" />

  <AppDialog :open="activationOpen" title="功能未解锁" @close="activationOpen = false">
    <p>激活授权码后即可记账和编辑流水。浏览已有账目、备份和更新不受影响。</p>
    <template #actions>
      <button class="button secondary" type="button" @click="router.back()">暂不</button>
      <button class="button primary" type="button" @click="router.replace('/settings/license')">去激活</button>
    </template>
  </AppDialog>
  <AppDialog :open="deleteOpen" title="确认删除流水" @close="deleteOpen = false">
    <p>删除后将从统计和报表中移除。如果可能需要找回，请先在设置中导出备份。</p>
    <template #actions>
      <button class="button secondary" type="button" @click="deleteOpen = false">取消</button>
      <button class="button danger" type="button" :disabled="deleting" @click="remove"><Trash2 :size="19" />{{ deleting ? '删除中' : '确认删除' }}</button>
    </template>
  </AppDialog>
</template>

<style scoped>
.record-page { min-height: 100dvh; background: var(--color-bg); }
.record-header { position: sticky; z-index: 10; top: 0; display: grid; grid-template-columns: 76px 1fr 76px; min-height: calc(56px + var(--safe-top)); align-items: end; padding: var(--safe-top) 4px 8px; border-bottom: 1px solid var(--color-border); background: var(--color-surface); }
.record-header h1 { align-self: center; margin: 0; text-align: center; font-size: 18px; }
.header-button, .save-button { min-height: 48px; border: 0; background: transparent; color: var(--color-primary); }
.header-button { display: grid; width: 48px; place-items: center; border-radius: 50%; }
.save-button { display: inline-flex; align-items: center; justify-content: center; gap: 4px; font-weight: 700; }
.type-wrap { position: sticky; z-index: 9; top: calc(56px + var(--safe-top)); padding: 10px 16px; background: var(--color-surface); }
.record-form { width: min(calc(100% - 32px), 688px); margin: 16px auto; overflow: hidden; }
.form-row { display: grid; width: 100%; min-height: 68px; grid-template-columns: 80px minmax(0, 1fr); align-items: center; gap: 12px; padding: 8px 16px; border: 0; border-bottom: 1px solid var(--color-border); background: var(--color-surface); color: var(--color-text-secondary); text-align: left; }
.form-row:last-of-type { border-bottom: 0; }
.form-row input { width: 100%; min-height: 48px; border: 0; outline: none; background: transparent; color: var(--color-text); text-align: right; font-size: 16px; }
.form-row input.expense, .form-row input.income { font-size: 22px; font-weight: 800; font-variant-numeric: tabular-nums; }
.form-row input.expense { color: var(--color-expense); }
.form-row input.income { color: var(--color-income); }
.row-value { display: flex; width: 100%; min-width: 0; align-items: center; justify-content: flex-end; gap: 7px; color: var(--color-text); font-weight: 600; }
